node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('utf8');

// Find the reminder ID and extract surrounding context more carefully
const id = 'f2da51e1-c1cb-4931-a156-f283db2214a1';
const idx = text.indexOf(id);
if (idx >= 0) {
  const start = Math.max(0, idx - 50);
  const end = Math.min(text.length, idx + 300);
  const slice = buf.slice(start, end);
  // Print hex + ascii for analysis
  const hex = [];
  for (let i = 0; i < slice.length; i++) {
    hex.push(slice[i].toString(16).padStart(2,'0'));
  }
  console.log('Raw bytes around the record:');
  console.log(slice.toString('utf8'));
  console.log('---');
  // Look for float64 values (reminder_timestamp) near the ID
  // Search for 8-byte doubles that could be POSIX timestamps (around 1.7-1.8 billion)
  for (let i = start; i < Math.min(buf.length, end + 100); i++) {
    // SQLite stores floats as big-endian IEEE 754
    if (i + 8 <= buf.length) {
      const dBE = buf.readDoubleBE(i);
      if (dBE > 1.7e9 && dBE < 1.9e9) {
        console.log('Possible BE timestamp at offset', i, ':', dBE, new Date(dBE * 1000).toISOString());
      }
    }
  }
}
"

