const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const id = 'f2da51e1-c1cb-4931-a156-f283db2214a1';
const idx = buf.indexOf(id);

// The ts_reminders table columns: reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at
// In SQLite B-tree pages, the fields are serialized sequentially
// Let's look for all 8-byte float patterns near this record

for (let i = idx - 100; i < idx + 200; i++) {
  if (i + 8 <= buf.length && i >= 0) {
    const dBE = buf.readDoubleBE(i);
    if (dBE > 1.0e9 && dBE < 2.0e9) {
      console.log('Offset', i, 'BE float64:', dBE, '->', new Date(dBE * 1000).toISOString());
    }
  }
}
"

